-  while (req() > 1) {
-    uint last = req() - 1;
-    assert(in(last) == nullptr || in(last)->is_top(), "only dead inputs should remain");
-    del_req(last);
-  }
-  Node* root_node = Compile::current()->root();
-  root_node->add_req(this);
-  igvn->_worklist.push(root_node);
-  igvn->set_type(this, bottom_type());
-}
